profile.themeCSS:
/* BUYaSOUL canon: obsidian x gold neo-cyberpunk (auto-scoped to #user-profile-canvas) */
.upc{background:radial-gradient(1100px 700px at 15% -10%,rgba(255,209,102,0.07),transparent 55%),radial-gradient(900px 500px at 100% 110%,rgba(139,92,246,0.07),transparent 55%),#0a0a0f}
.upc-card{background:rgba(255,209,102,0.045);border:1px solid rgba(255,209,102,0.16);border-radius:18px;box-shadow:0 18px 60px rgba(0,0,0,0.45)}
.upc-card h3{color:#FFD166}
.upc-sub{color:#9a937f}
.upc-handle{color:#ffffff}
.upc-handle em{color:#FFD166;font-style:normal}
.upc-mood{color:#FFD166}
.upc-bio{color:#cfc8b8}
.upc-empty{color:#9a937f}
.upc-ava img{border:2px solid rgba(255,209,102,0.45)}
.upc-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:10px}
.upc-soul{background:#0d0d13;border:1px solid rgba(255,209,102,0.22);border-radius:14px;padding:12px;text-align:center;transition:transform .15s ease,box-shadow .15s ease}
.upc-soul:hover{transform:translateY(-2px);box-shadow:0 12px 40px rgba(255,209,102,0.12)}
.upc-soul .nm{color:#fff}
.upc-soul .ty{color:#FFD166;text-transform:uppercase;letter-spacing:1px}
.upc-btn{border:1px solid rgba(255,209,102,0.3);color:#e8d9a8}
.upc-btn.prim{background:linear-gradient(135deg,#FFD166,#B8860B);border:none;color:#12100a;font-weight:700}
.upc-btn.cyan{background:linear-gradient(135deg,#00D4FF,#0284C7);border:none;color:#04141a;font-weight:700}
.upc-tchip{border:1px solid rgba(255,209,102,0.25);color:#e8d9a8}
.upc-guest{background:rgba(255,209,102,0.04)}
.upc-guest .gav{background:linear-gradient(135deg,rgba(255,209,102,0.2),rgba(139,92,246,0.2));color:#FFD166}
.upc-guest .gt b{color:#FFD166}
.upc-guest .gm{color:#9a937f}
.upc-rm{color:#9a937f}
.upc-guestform textarea{border-color:rgba(255,209,102,0.25)}
#upcNoteBtn{background:linear-gradient(135deg,#FFD166,#B8860B);border:none;color:#12100a;font-weight:700}
